function validate([s1, n1, s2, n2]) {
  if (s1.length < 1 || s1.length > 100 || s2.length < 1 || s2.length > 100) return 's1 and s2 need 1 to 100 characters each.';
  if (!/^[a-z]+$/.test(s1) || !/^[a-z]+$/.test(s2)) return 's1 and s2 use lowercase letters only.';
  if (n1 < 1 || n1 > 1000000 || n2 < 1 || n2 > 1000000) return 'n1 and n2 are between 1 and 10^6.';
  return null;
}

