function getMaxRepetitions(s1, n1, s2, n2) {
  const seen = new Map();
  let index = 0;
  let count = 0;
  let block = 0;

  while (block < n1) {
    for (const ch of s1) {
      if (ch === s2[index]) {
        index++;
        if (index === s2.length) {
          index = 0;
          count++;
        }
      }
    }
    block++;

    if (seen.has(index)) {
      const [prevBlock, prevCount] = seen.get(index);
      const cycleBlocks = block - prevBlock;
      const cycleCount = count - prevCount;
      const cycles = Math.floor((n1 - block) / cycleBlocks);
      block += cycles * cycleBlocks;
      count += cycles * cycleCount;
      seen.clear();
    }
    seen.set(index, [block, count]);
  }
  return Math.floor(count / n2);
}

