function getMaxRepetitions(s1, n1, s2, n2) {
  // For every starting position in s2, precompute where one copy of s1 leaves us and how many s2 copies it completes.
  const nextPos = [], gained = [];
  for (let start = 0; start < s2.length; start++) {
    let j = start, done = 0;
    for (let i = 0; i < s1.length; i++) {
      if (s1[i] === s2[j]) { j++; if (j === s2.length) { j = 0; done++; } }
    }
    nextPos.push(j);
    gained.push(done);
  }
  let pos = 0, total = 0;
  for (let b = 0; b < n1; b++) { total += gained[pos]; pos = nextPos[pos]; }
  return Math.floor(total / n2);
}

