function generate(rand, size) {
  const word = (n, letters) => { let s = ''; for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * letters.length)]; return s; };
  if (size === 'large') {
    const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 3 + Math.floor(rand() * 10));
    return [word(100, letters), 1 + Math.floor(rand() * 1000000), word(100, letters), 1 + Math.floor(rand() * 1000)];
  }
  const letters = rand() < 0.85 ? 'abc' : 'abcd';
  const s1 = word(1 + Math.floor(rand() * 6), 'abc');
  const s2 = word(1 + Math.floor(rand() * 4), letters);
  return [s1, 1 + Math.floor(rand() * 40), s2, 1 + Math.floor(rand() * 5)];
}
